import {makeRoute,elevation} from './geography.js';
import {createWeather,sampleWeather} from './weather.js';
export const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
export const WAYPOINTS=[{x:0,y:180,z:-1000},{x:-420,y:510,z:-2600},{x:480,y:880,z:-4400},{x:-550,y:1200,z:-6400},{x:520,y:1100,z:-8400},{x:250,y:650,z:-10300},{x:0,y:250,z:-11800},{x:0,y:65,z:-13000}];
export const RUNWAY={start:-13300,end:-14400,width:100};
export function createFlight(mission,origin,maxSpeed=226,options={}){const route=makeRoute(origin,mission.i);return{route,weatherCells:options.weather===false?[]:createWeather(options.seed??Math.floor(Math.random()*10000)),weather:{intensity:0,lift:1},x:0,y:4,z:320,yaw:0,pitch:0,bank:0,controlPitch:0,controlBank:0,rollDisturbance:0,pitchDisturbance:0,speed:0,throttle:.8,gate:0,elapsed:0,limit:240,remaining:240,verticalSpeed:0,airborne:false,touchedDown:false,landed:false,failed:null,cloud:0,mission:{...mission},origin,credited:false,maxSpeed:Math.max(125,Math.min(190,maxSpeed/3.6*2)),phase:'TAKEOFF',distance:0};}
export function terrainHeight(x,z){const coast=1250+Math.sin(z*.00065)*240;const bank=Math.max(0,Math.abs(x)-900);if(x>coast)return -12;return Math.max(0,(Math.sin(x*.0018+z*.0007)*.5+.5)*(Math.sin(z*.0011)*.5+.5)*Math.min(620,bank*.34));}
export function stepFlight(f,keys,dt){if(f.failed||f.landed)return;f.elapsed+=dt;f.remaining=Math.max(0,f.limit-f.elapsed);if(!f.remaining){f.failed='运输超时';return}f.throttle=clamp(f.throttle+((keys.arrowup?1:0)-(keys.arrowdown?1:0))*dt*.4,0,1);const targetSpeed=f.throttle*f.maxSpeed;f.speed+=clamp(targetSpeed-f.speed,-19*dt,15*dt);const turn=(keys.a||keys.arrowleft?1:0)-(keys.d||keys.arrowright?1:0),pitch=(keys.w?1:0)-(keys.s?1:0);const blend=Math.min(1,dt*3);f.controlBank+=(turn*.85-f.controlBank)*blend;f.yaw+=turn*dt*(f.airborne?.65:.16);f.controlPitch+=(pitch*.56-f.controlPitch)*blend;if(keys[' ']){f.controlPitch=0;f.controlBank*=1-blend}f.bank=f.controlBank+f.rollDisturbance;f.pitch=f.controlPitch+f.pitchDisturbance;if(!f.airborne&&f.speed>44&&f.pitch>.07){f.airborne=true;f.touchedDown=false}f.weather=sampleWeather(f);const w=f.weather;if(f.airborne){f.rollDisturbance=clamp(f.rollDisturbance*Math.exp(-dt*.8)+w.roll*dt,-.65,.65);f.pitchDisturbance=clamp(f.pitchDisturbance*Math.exp(-dt)+w.pitch*dt,-.22,.22);f.bank=clamp(f.controlBank+f.rollDisturbance,-1.2,1.2);f.pitch=clamp(f.controlPitch+f.pitchDisturbance,-.7,.7);f.yaw+=Math.sin(f.bank)*w.intensity*.08*dt;f.speed=Math.max(0,f.speed-w.intensity*4*dt)}f.verticalSpeed=f.airborne?Math.sin(f.pitch)*f.speed*w.lift+w.windY+(w.lift-1)*22:0;if(f.airborne&&f.speed<40)f.verticalSpeed-=(40-f.speed)*.6;f.x-=Math.sin(f.yaw)*f.speed*dt; if(f.airborne)f.x+=w.windX*dt;f.z-=Math.cos(f.yaw)*f.speed*dt;f.y+=f.verticalSpeed*dt;f.distance+=f.speed*dt;f.y=Math.min(f.y,2400);const destination=f.z<RUNWAY.start&&f.z>RUNWAY.end&&Math.abs(f.x)<RUNWAY.width/2;const ground=Math.max(0,elevation(f.route,f.x,f.z))+4;if(f.airborne&&f.y<=ground){if(destination&&f.gate===WAYPOINTS.length&&f.speed<=78&&Math.abs(f.bank)<.26&&Math.abs(f.yaw)<.2&&f.verticalSpeed>=-15){f.y=4;f.airborne=false;f.touchedDown=true;f.pitch=0;}else{f.failed=elevation(f.route,f.x,f.z)<0?'触及海面 / 运输失败':'着陆条件不满足 / 接触地面';return}}if(!f.airborne)f.y=ground;if(!f.airborne&&!f.touchedDown&&(f.z< -650||Math.abs(f.x)>50)){f.failed='冲出起飞跑道';return}if(f.touchedDown){f.phase='ROLLOUT';if(!destination){f.failed='冲出降落跑道';return}if(f.speed<12){f.landed=true;return}}else f.phase=!f.airborne?'TAKEOFF':f.gate<2?'CLIMB':f.gate<5?'CRUISE':f.gate<7?'DESCENT':'APPROACH';if(Math.abs(f.x)>6500||f.z< -15500||f.z>2500){f.failed='飞离任务空域';return}const g=WAYPOINTS[f.gate];if(g&&Math.abs(f.z-g.z)<100&&Math.hypot(f.x-g.x,f.y-g.y)<220)f.gate++;}
export function recoverFlight(f){const g=WAYPOINTS[f.gate]||{x:0,y:90,z:-13200};f.x=g.x;f.y=g.y;f.z=g.z+550;f.yaw=0;f.pitch=0;f.bank=0;f.controlPitch=0;f.controlBank=0;f.rollDisturbance=0;f.pitchDisturbance=0;f.speed=85;f.throttle=.65;f.airborne=true;f.touchedDown=false;f.elapsed+=15;}
export function landingGuidance(f){return f.touchedDown?'保持中线，按 ↓ 减速至 12 kt 以下':f.gate===WAYPOINTS.length?'对准跑道 · 降至 4 m · 空速 < 76 kt · 下降率 < 15 m/s':'跟随金色光环 · W 抬头 / S 低头';}
